arguments.command:
curl -s "https://api.box.com/2.0/folders/8100/items?limit=200&fields=id,name,type,owned_by,created_by" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for e in d.get('entries',[]):
    if e['type']=='folder':
        ob=e.get('owned_by') or {}
        cb=e.get('created_by') or {}
        print(e['id'], e['name'], '| owner:', ob.get('id'), ob.get('name'), '| created_by:', cb.get('id'), cb.get('name'))
"

